    const lexer = new Lexer(source);
    const tokenBuffer = new TokenBuffer(lexer, { preserveNewlines: false });

    // 2. Parse: TokenBuffer → Module AST (supports fn/let/if/while/for)
    const parser = new Parser(tokenBuffer);
